{
  "research": [
    {
      "id": "R1",
      "title": "Sensitivity of Extractive Question Answering to Distractor Passages",
      "bullets": [
        "Designed controlled experiments varying distractor relevance and passage ordering to examine context sensitivity in pretrained extractive question answering models.",
        "Analyzed answer span errors across question types, separating failures associated with lexical overlap from those involving competing answer candidates."
      ]
    },
    {
      "id": "R2",
      "title": "Domain Shift and Calibration in Sentiment Classification",
      "bullets": [
        "Designed cross-domain evaluation protocols comparing linear and transformer sentiment classifiers under matched preprocessing, training partitions, and label availability.",
        "Analyzed calibration curves and misclassified examples to characterize confidence changes associated with domain vocabulary, negation, and mixed sentiment."
      ]
    }
  ],
  "publications": [],
  "work": [
    {
      "id": "W1",
      "title": "Maintenance of Data Import and Validation Utilities",
      "bullets": [
        "Implemented assigned updates to Python import utilities, adding schema checks and clearer error messages for malformed tabular records.",
        "Wrote regression tests for parsing edge cases and investigated reported import failures by tracing validation logic and reproducing problematic inputs."
      ]
    }
  ],
  "projects": [
    {
      "id": "T1",
      "title": "Comparing Sparse and Dense Retrieval for FAQ Matching",
      "bullets": [
        "Implemented term-weighted and pretrained sentence-embedding retrieval baselines for matching user questions to relevant FAQ entries using a shared evaluation split.",
        "Compared ranking metrics and inspected retrieval errors involving paraphrases, rare terminology, and questions sharing keywords but expressing different intents."
      ]
    },
    {
      "id": "T2",
      "title": "Sequence Labeling Approaches to Named Entity Recognition",
      "bullets": [
        "Implemented a feature-based sequence tagger and fine-tuned a pretrained token classifier using consistent entity labels and sentence-level data partitions.",
        "Compared entity-level precision and recall, examining boundary errors, ambiguous names, and tokenization differences through manually reviewed prediction examples."
      ]
    },
    {
      "id": "T3",
      "title": "Extractive Summarization with Frequency and Graph-Based Ranking",
      "bullets": [
        "Implemented sentence-frequency scoring and graph-based sentence ranking for document summarization, applying identical preprocessing and summary length constraints.",
        "Compared reference overlap and reviewed selected sentences for redundancy, topic coverage, and dependence on context omitted from generated summaries."
      ]
    },
    {
      "id": "T4",
      "title": "Character and Word Representations for Noisy Text Classification",
      "bullets": [
        "Implemented character-based and word-based text classification pipelines, evaluating both on clean inputs and controlled spelling and whitespace perturbations.",
        "Compared classification performance across perturbation types and inspected feature weights to identify sensitivity to fragmented words and altered character sequences."
      ]
    }
  ]
}
